import rules from '@/lib/state-page-rules.data.json';

/**
 * What a state's public page may say about its rule, beyond the citation.
 *
 * Generated by scripts/build-state-page-rules.py, which fetches each cited
 * state's source again and keeps only the quote and the required elements it
 * can find there. Nothing here is typed by hand, and nothing comes from the
 * research file unless the source still says it.
 */
export type StatePageRule = {
  citation: string;
  citationTitle: string;
  quote: string;
  elements: string[];
  elementsDropped: number;
  sourceUrl: string;
};

export const STATE_RULES_CHECKED_ON: string = rules.checkedOn;

const states = rules.states as Record<string, StatePageRule>;

function squash(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '');
}

/**
 * The rule to show for a state, or null.
 *
 * `printedCitation` is what the state's live template prints at the foot of
 * the page. The checked rule is shown only when that citation names it, so a
 * template that is later re-cited to a different rule, or demoted to cite
 * nothing, stops showing the old rule on its own rather than waiting for
 * somebody to remember this file. West Virginia is the one exception: its
 * template reproduces the state's form, so it prints the form's name rather
 * than the manual chapter that requires the form.
 */
export function stateRule(code: string, printedCitation: string | null): StatePageRule | null {
  const rule = states[code];
  if (!rule || !printedCitation) return null;
  if (code === 'US-WV' && /^Reproduces /.test(printedCitation)) return rule;
  return squash(printedCitation).includes(squash(rule.citation)) ? rule : null;
}

/** "14 October 2026", spelled out so no locale or engine can disagree about it. */
export function checkedOnLabel(): string {
  const [y, m, d] = STATE_RULES_CHECKED_ON.split('-').map(Number);
  const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  return `${d} ${months[m - 1]} ${y}`;
}
